/* Igor Time · the harmony course rewritten for people who have never studied music (14 Nov 2026, Fabio:
   "it must not take anything for granted, at least the first 80–100 lessons: show the piano, give little tricks").
   HM_CARDS[n] replaces the blackboard cards of lesson n (1 = the first lesson); HM_EX[n] replaces its exercises.
   A card is [en, it, demo]; a demo can be a staff {cols:[...]} or a keyboard {kbd:{lo,hi,on,arcs,names,top,cap}, cols:[... to hear]}. */
(function(){
const K=(lo,hi,on,more)=>({lo,hi,on:on||{},names:1,...(more||{})});
const C={},E={};
/* ======================= 1. SOUNDS AND DISTANCES ======================= */
C[1]=[
 ['Good morning, I am <b>Arnold Schönbigor</b>. Here we start from zero: you don’t need to know anything about music. Look at the piano on the board.','Buongiorno, sono <b>Arnold Schönbigor</b>. Qui si parte da zero: non serve sapere niente di musica. Guarda il pianoforte sulla lavagna.',{kbd:K('C4','B5',{},{names:0})}],
 ['The black keys come in little groups: <b>two</b>, then <b>three</b>, then two, then three… They are your map. Without them, every white key would look the same.','I tasti neri sono in gruppetti: <b>due</b>, poi <b>tre</b>, poi due, poi tre… Sono la tua mappa. Senza di loro, i tasti bianchi sembrerebbero tutti uguali.',{kbd:K('C4','B5',{'C#4':'y','D#4':'y','F#4':'p','G#4':'p','A#4':'p'},{names:0,cap:['two… three… two… three…','due… tre… due… tre…']})}],
 ['The white key just left of the two black keys is <b>C</b> (in Italian, <b>Do</b>). Then come D, E, F, G, A, B, and again C. Only seven names, repeating.','Il tasto bianco subito a sinistra dei due tasti neri è il <b>Do</b>. Poi vengono Re, Mi, Fa, Sol, La, Si, e di nuovo Do. Solo sette nomi, che si ripetono.',{kbd:K('C4','C5',{'C4':'y','C5':'y'}),cols:['C4|D4|E4|F4|G4|A4|B4|C5']}],
 ['Now the most important idea. From one key to the very next one (white or black, no matter) there is the smallest distance in music: a <b>semitone</b>. It’s one tiny step.','Ora l’idea più importante. Da un tasto a quello subito accanto (bianco o nero, non importa) c’è la distanza più piccola della musica: il <b>semitono</b>. È un passettino.',{kbd:K('C4','C5',{'C4':'y','C#4':'y'},{arcs:[['C4','C#4',['semitone','semitono'],1]]}),cols:['C4|C#4']}],
 ['The trick: look between two white keys. <b>No black key in between</b>? Then they are as close as possible: a <b>semitone</b>. It happens only twice: E–F and B–C.','Il trucco: guarda in mezzo a due tasti bianchi. <b>Nessun tasto nero in mezzo</b>? Allora sono vicinissimi: un <b>semitono</b>. Succede solo due volte: Mi–Fa e Si–Do.',{kbd:K('C4','C5',{'E4':'p','F4':'p','B4':'p','C5':'p'},{arcs:[['E4','F4',['semitone','semitono'],1],['B4','C5',['semitone','semitono'],1]]}),cols:['E4|F4','B4|C5']}],
 ['<b>A black key in between</b>? Then the distance is two semitones, and two semitones make a <b>tone</b>. C–D is a tone: in the middle there is a black key. F–G too.','<b>C’è un tasto nero in mezzo</b>? Allora la distanza è di due semitoni, e due semitoni fanno un <b>tono</b>. Do–Re è un tono: in mezzo c’è un tasto nero. Anche Fa–Sol.',{kbd:K('C4','C5',{'C4':'y','D4':'y','F4':'y','G4':'y'},{arcs:[['C4','D4',['tone','tono']],['F4','G4',['tone','tono']]]}),cols:['C4|D4','F4|G4']}],
 ['Listen to the difference: the semitone is a squeeze, the tone is a normal step. Remember: <b>black key in between = tone; nothing in between = semitone</b>.','Ascolta la differenza: il semitono è uno sfioramento, il tono è un passo normale. Ricorda: <b>tasto nero in mezzo = tono; niente in mezzo = semitono</b>.',{kbd:K('C4','C5',{'E4':'p','F4':'p','F#4':'y','G#4':'y'},{arcs:[['E4','F4',['semitone','semitono'],1],['F#4','G#4',['tone','tono']]]}),cols:['E4|F4','F#4|G#4']}]];
E[1]=[['kbName'],['kbSemi',{white:1}],['kbSemi',{white:1}],['kbSemi']];
C[2]=[
 ['The black keys have no names of their own: they borrow the names of their neighbours. Look at the black key between C and D.','I tasti neri non hanno un nome loro: lo prendono in prestito dai vicini. Guarda il tasto nero tra Do e Re.',{kbd:K('C4','E4',{'C#4':'y'})}],
 ['Seen from C, it is one step <b>up</b>: we call it <b>C sharp</b>, C♯. The sharp ♯ means “one semitone higher”.','Visto dal Do, è un passo <b>in su</b>: lo chiamiamo <b>Do diesis</b>, Do♯. Il diesis ♯ vuol dire “un semitono più su”.',{kbd:K('C4','E4',{'C4':'g','C#4':'y'},{arcs:[['C4','C#4',['up','su'],1]]}),cols:['C4|C#4']}],
 ['Seen from D, the same key is one step <b>down</b>: <b>D flat</b>, D♭. The flat ♭ means “one semitone lower”.','Visto dal Re, lo stesso tasto è un passo <b>in giù</b>: <b>Re bemolle</b>, Re♭. Il bemolle ♭ vuol dire “un semitono più giù”.',{kbd:K('C4','E4',{'D4':'g','C#4':'y'},{arcs:[['D4','C#4',['down','giù'],1]]}),cols:['D4|Db4']}],
 ['A little trick to remember: the ♯ looks like a ladder going <b>up</b>; the ♭ looks like a little balloon that has gone <b>flat</b> and sinks.','Un trucchetto per ricordare: il ♯ sembra una scaletta che fa <b>salire</b>; il ♭ sembra un palloncino <b>sgonfio</b> che scende.'],
 ['Sharps and flats work on white keys too: E♯ is just F, and C♭ is just B. And the <b>natural ♮</b> cancels them: the note goes back to its plain white key.','Diesis e bemolli funzionano anche sui tasti bianchi: Mi♯ è semplicemente il Fa, e Do♭ è il Si. Il <b>bequadro ♮</b> li cancella: la nota torna al suo tasto bianco normale.',{cols:['F4=Fa','F#4=Fa♯','B4=Si','Bb4=Si♭']}]];
E[2]=[['kbBlack'],['kbUp',{semi:1}],['accName'],['accName']];
C[3]=[
 ['Play <b>every</b> key, white and black, one after the other, from C to the next C: twelve little steps of a semitone. This is the <b>chromatic scale</b>.','Suona <b>tutti</b> i tasti, bianchi e neri, uno dopo l’altro, da un Do al Do successivo: dodici passettini di un semitono. È la <b>scala cromatica</b>.',{kbd:K('C4','C5',{'C4':'y','C#4':'y','D4':'y','D#4':'y','E4':'y','F4':'y','F#4':'y','G4':'y','G#4':'y','A4':'y','A#4':'y','B4':'y','C5':'y'},{names:0}),cols:['C4|C#4|D4|D#4|E4|F4|F#4|G4|G#4|A4|A#4|B4|C5']}],
 ['So inside an octave (from a C to the next C) there are only <b>12 different sounds</b>: 7 white keys and 5 black keys. All the music you know is made with these twelve.','Quindi dentro un’ottava (da un Do al Do dopo) ci sono solo <b>12 suoni diversi</b>: 7 tasti bianchi e 5 neri. Tutta la musica che conosci è fatta con questi dodici.'],
 ['You have already seen that one key can have two names: C♯ and D♭ are the <b>same sound</b>. Two names for one key: we call them <b>enharmonic</b> notes. Like a person with a name and a nickname.','Hai già visto che un tasto può avere due nomi: Do♯ e Re♭ sono lo <b>stesso suono</b>. Due nomi per un tasto: le chiamiamo note <b>enarmoniche</b>. Come una persona con nome e soprannome.',{kbd:K('C4','E4',{'C#4':'y'},{names:2}),cols:['C#4=Do♯','Db4=Re♭']}]];
E[3]=[['kbBlack'],['enh'],['kbCount',{max:4}]];
C[4]=[
 ['A <b>scale</b> is a staircase of notes. The most common one is the <b>major scale</b>: play the white keys from C to C. It sounds cheerful and complete, like “do-re-mi” in the song.','Una <b>scala</b> è una scalinata di note. La più comune è la <b>scala maggiore</b>: suona i tasti bianchi da Do a Do. Suona allegra e completa, come il “do-re-mi” della canzone.',{kbd:K('C4','C5',{'C4':'y','D4':'y','E4':'y','F4':'y','G4':'y','A4':'y','B4':'y','C5':'y'}),cols:['C4|D4|E4|F4|G4|A4|B4|C5']}],
 ['Look at its steps with our trick. C–D: a black key in between, a tone. D–E: tone. E–F: nothing in between, a <b>semitone</b>. Then F–G, G–A, A–B: three tones. B–C: <b>semitone</b>.','Guarda i suoi gradini con il nostro trucco. Do–Re: tasto nero in mezzo, tono. Re–Mi: tono. Mi–Fa: niente in mezzo, <b>semitono</b>. Poi Fa–Sol, Sol–La, La–Si: tre toni. Si–Do: <b>semitono</b>.',{kbd:K('C4','C5',{'E4':'p','F4':'p','B4':'p','C5':'p'},{arcs:[['C4','D4',['T','T']],['D4','E4',['T','T']],['E4','F4',['S','S'],1],['F4','G4',['T','T']],['G4','A4',['T','T']],['A4','B4',['T','T']],['B4','C5',['S','S'],1]]})}],
 ['So the recipe of every major scale is: <b>tone, tone, semitone, tone, tone, tone, semitone</b>. Say it like a little poem: T-T-S, T-T-T-S.','Quindi la ricetta di ogni scala maggiore è: <b>tono, tono, semitono, tono, tono, tono, semitono</b>. Dilla come una filastrocca: T-T-S, T-T-T-S.'],
 ['With this recipe you can start a major scale from any key. Starting from G, the seventh step must be a tone higher than E: on the keyboard it lands on the black key, F♯.','Con questa ricetta puoi cominciare una scala maggiore da qualunque tasto. Partendo dal Sol, il settimo gradino deve stare un tono sopra il Mi: sulla tastiera cade sul tasto nero, il Fa♯.',{kbd:K('G4','G5',{'G4':'y','A4':'y','B4':'y','C5':'y','D5':'y','E5':'y','F#5':'p','G5':'y'}),cols:['G4|A4|B4|C5|D5|E5|F#5|G5']}]];
E[4]=[['steps'],['kbSemi'],['steps'],['scaleBuild',{maxf:1}]];
C[5]=[
 ['An <b>interval</b> is simply the distance between two notes. To give it a number, count the note names from the first to the second, <b>both included</b>.','Un <b>intervallo</b> è semplicemente la distanza tra due note. Per dargli un numero, conta i nomi delle note dalla prima alla seconda, <b>comprese tutte e due</b>.'],
 ['C to E: count “C, D, E” — three names, so it is a <b>third</b>. C to G: C, D, E, F, G — five, a <b>fifth</b>. C to the next C: eight, an <b>octave</b>.','Da Do a Mi: conta “Do, Re, Mi” — tre nomi, quindi è una <b>terza</b>. Da Do a Sol: Do, Re, Mi, Fa, Sol — cinque, una <b>quinta</b>. Da Do al Do dopo: otto, un’<b>ottava</b>.',{kbd:K('C4','C5',{'C4':'y','D4':'g','E4':'y'},{top:{'C4':'1','D4':'2','E4':'3'}}),cols:['C4|E4','C4|G4','C4|C5']}],
 ['Careful: count the names, not the keys. The black keys don’t count here, and you always start from 1, never from 0. The most common mistake is forgetting to count the first note!','Attenzione: si contano i nomi, non i tasti. Qui i tasti neri non contano, e si parte sempre da 1, mai da 0. L’errore più comune è dimenticare di contare la prima nota!'],
 ['On the staff it is even easier: from a line to the next line is a third; from a line to the space just above, a second. Like rungs of a ladder.','Sul pentagramma è ancora più facile: da una riga alla riga successiva c’è una terza; da una riga allo spazio subito sopra, una seconda. Come i pioli di una scala a pioli.',{cols:['C4|E4=3','E4|F4=2','C4|G4=5']}]];
C[6]=[
 ['Two intervals with the same number can be a little different. C–E and C–E♭ are both thirds (C, D, E), but one is a semitone bigger. Now we count the <b>semitones</b> too.','Due intervalli con lo stesso numero possono essere un po’ diversi. Do–Mi e Do–Mi♭ sono tutti e due terze (Do, Re, Mi), ma una è più grande di un semitono. Ora contiamo anche i <b>semitoni</b>.'],
 ['C to E: count the keys you pass, black ones too: C♯, D, D♯, E — 4 semitones. That is a <b>major third</b>: bright, happy.','Da Do a Mi: conta i tasti che attraversi, anche quelli neri: Do♯, Re, Re♯, Mi — 4 semitoni. È una <b>terza maggiore</b>: luminosa, allegra.',{kbd:K('C4','G4',{'C4':'y','E4':'y'},{top:{'C#4':'1','D4':'2','D#4':'3','E4':'4'}}),cols:['C4 E4']}],
 ['C to E♭: only 3 semitones. That is a <b>minor third</b>: softer, a bit sad. Same number, different colour.','Da Do a Mi♭: solo 3 semitoni. È una <b>terza minore</b>: più morbida, un po’ malinconica. Stesso numero, colore diverso.',{kbd:K('C4','G4',{'C4':'y','D#4':'p'},{top:{'C#4':'1','D4':'2','D#4':'3'}}),cols:['C4 Eb4']}],
 ['Seconds work the same way: a <b>major second</b> is a tone (2 semitones), a <b>minor second</b> is a semitone (1). Major = the bigger one, minor = the smaller one.','Le seconde funzionano allo stesso modo: la <b>seconda maggiore</b> è un tono (2 semitoni), la <b>seconda minore</b> è un semitono (1). Maggiore = la più grande, minore = la più piccola.',{kbd:K('C4','G4',{'E4':'y','F#4':'y','F4':'p'}),cols:['E4|F#4=2M','E4|F4=2m']}]];
E[6]=[['kbCount',{max:4}],['ivQual',{nums:[2,3]}],['ivQual',{nums:[3]}],['ivUp',{nums:[2,3]}]];
C[7]=[
 ['Some intervals sound so stable and clean that we call them <b>perfect</b>: the fourth, the fifth and the octave.','Alcuni intervalli suonano così stabili e puliti che li chiamiamo <b>giusti</b>: la quarta, la quinta e l’ottava.'],
 ['C–F is a perfect <b>fourth</b>: 5 semitones. It sounds like the start of “Here comes the bride”.','Do–Fa è una <b>quarta giusta</b>: 5 semitoni. Suona come l’inizio della marcia nuziale.',{kbd:K('C4','C5',{'C4':'y','F4':'y'}),cols:['C4|F4','C4 F4']}],
 ['C–G is a perfect <b>fifth</b>: 7 semitones. Strong and open, like the start of the “Star Wars” theme.','Do–Sol è una <b>quinta giusta</b>: 7 semitoni. Forte e aperta, come l’inizio del tema di “Guerre stellari”.',{kbd:K('C4','C5',{'C4':'y','G4':'y'}),cols:['C4|G4','C4 G4']}],
 ['C to the next C is the <b>octave</b>: 12 semitones. The two notes have the same name and sound almost like one: the same note, higher. Like a child and an adult singing together.','Da un Do al Do dopo c’è l’<b>ottava</b>: 12 semitoni. Le due note hanno lo stesso nome e suonano quasi come una sola: la stessa nota, più in alto. Come un bambino e un adulto che cantano insieme.',{kbd:K('C4','C5',{'C4':'y','C5':'y'}),cols:['C4|C5','C4 C5']}],
 ['A trick for fourths and fifths on white keys: they are all perfect, except one. F–B is a fourth that is too big, and B–F a fifth that is too small. Remember the odd couple: <b>F and B</b>.','Un trucco per quarte e quinte sui tasti bianchi: sono tutte giuste, tranne una. Fa–Si è una quarta troppo grande, e Si–Fa una quinta troppo piccola. Ricorda la coppia strana: <b>Fa e Si</b>.',{kbd:K('C4','C5',{'F4':'p','B4':'p'}),cols:['F4 B4']}]];
C[8]=[
 ['Sixths and sevenths are bigger, but you measure them the same way: count the names for the number, count the semitones for the colour.','Seste e settime sono più grandi, ma si misurano allo stesso modo: conti i nomi per il numero, conti i semitoni per il colore.'],
 ['C–A is a <b>major sixth</b> (9 semitones): sweet and wide, like the start of “My Bonnie”. C–A♭ is a <b>minor sixth</b> (8): more melancholic.','Do–La è una <b>sesta maggiore</b> (9 semitoni): dolce e ampia. Do–La♭ è una <b>sesta minore</b> (8): più malinconica.',{kbd:K('C4','C5',{'C4':'y','A4':'y','G#4':'p'}),cols:['C4 A4=6M','C4 Ab4=6m']}],
 ['C–B is a <b>major seventh</b> (11 semitones): almost an octave, it “itches”. C–B♭ is a <b>minor seventh</b> (10): restless, it wants to move on.','Do–Si è una <b>settima maggiore</b> (11 semitoni): quasi un’ottava, “pizzica”. Do–Si♭ è una <b>settima minore</b> (10): inquieta, vuole andare avanti.',{kbd:K('C4','C5',{'C4':'y','B4':'y','A#4':'p'}),cols:['C4 B4=7M','C4 Bb4=7m']}],
 ['A shortcut: a seventh is an octave minus a little. Major seventh = octave minus a semitone; minor seventh = octave minus a tone.','Una scorciatoia: la settima è un’ottava meno un pezzettino. Settima maggiore = ottava meno un semitono; settima minore = ottava meno un tono.']];
C[9]=[
 ['Turn an interval upside down: move the lower note up an octave. C–E (a third) becomes E–C (a sixth). This is the <b>inversion</b> of an interval.','Capovolgi un intervallo: sposta la nota sotto su di un’ottava. Do–Mi (una terza) diventa Mi–Do (una sesta). È il <b>rivolto</b> dell’intervallo.',{cols:['C4 E4=3','E4 C5=6']}],
 ['The magic number is <b>9</b>: a third becomes a sixth (3+6=9), a second becomes a seventh, a fourth becomes a fifth. And major becomes minor, minor becomes major; perfect stays perfect.','Il numero magico è <b>9</b>: la terza diventa sesta (3+6=9), la seconda diventa settima, la quarta diventa quinta. E maggiore diventa minore, minore diventa maggiore; giusto resta giusto.'],
 ['Some intervals sound calm and sweet: we call them <b>consonant</b> (thirds, sixths, fifths, octaves). Others are tense and rub: <b>dissonant</b> (seconds, sevenths). Not “ugly”: tension is what makes music move.','Alcuni intervalli suonano calmi e dolci: li chiamiamo <b>consonanti</b> (terze, seste, quinte, ottave). Altri sono tesi e stridono: <b>dissonanti</b> (seconde, settime). Non “brutti”: la tensione è ciò che fa muovere la musica.',{cols:['C4 E4=3','C4 G4=5','C4 D4=2','C4 B4=7']}]];
/* ======================= 2. KEYS ======================= */
C[11]=[
 ['Remember the recipe of the major scale: T-T-S, T-T-T-S. If you start from C, the white keys are enough. If you start from another key, some black keys are needed.','Ricordi la ricetta della scala maggiore: T-T-S, T-T-T-S. Se parti dal Do, bastano i tasti bianchi. Se parti da un altro tasto, servono alcuni tasti neri.'],
 ['Start from G: G, A, B, C, D, E… now we need a tone after E, and then a semitone to G. So the seventh note must be <b>F♯</b>, not F.','Parti dal Sol: Sol, La, Si, Do, Re, Mi… ora dopo il Mi serve un tono, e poi un semitono fino al Sol. Quindi la settima nota dev’essere <b>Fa♯</b>, non Fa.',{kbd:K('G4','G5',{'G4':'y','A4':'y','B4':'y','C5':'y','D5':'y','E5':'y','F#5':'p','G5':'y'}),cols:['G4|A4|B4|C5|D5|E5|F#5|G5=Sol maggiore']}],
 ['A scale with its notes is called a <b>key</b>: “G major” means “the notes of the G major scale”. A piece in G major uses mostly those seven notes.','Una scala con le sue note si chiama <b>tonalità</b>: “Sol maggiore” vuol dire “le note della scala di Sol maggiore”. Un brano in Sol maggiore usa soprattutto quelle sette note.'],
 ['To avoid writing ♯ in front of every F, we write it once, at the start of every line: the <b>key signature</b>. One sharp at the start = G major.','Per non scrivere ♯ davanti a ogni Fa, lo scriviamo una volta sola, all’inizio di ogni rigo: l’<b>armatura di chiave</b>. Un diesis all’inizio = Sol maggiore.',{key:1,cols:[]}]];
C[12]=[
 ['Do the same from D, A, E… each time you start a fifth higher, you need <b>one more sharp</b>. C has none, G one, D two, A three, E four.','Fai lo stesso da Re, La, Mi… ogni volta che parti una quinta più su, serve <b>un diesis in più</b>. Do non ne ha, Sol uno, Re due, La tre, Mi quattro.'],
 ['The sharps always arrive in the same order: <b>F, C, G, D, A, E, B</b>. A sentence to remember it: “<b>F</b>ather <b>C</b>harles <b>G</b>oes <b>D</b>own <b>A</b>nd <b>E</b>nds <b>B</b>attle”.','I diesis arrivano sempre nello stesso ordine: <b>Fa, Do, Sol, Re, La, Mi, Si</b>. Ripetilo come una filastrocca: “Fa-Do-Sol-Re-La-Mi-Si”.',{key:4,cols:[]}],
 ['The trick to name the key: look at the <b>last sharp</b> and go up one semitone. Last sharp G♯ → the key is A major.','Il trucco per dare il nome alla tonalità: guarda l’<b>ultimo diesis</b> e sali di un semitono. Ultimo diesis Sol♯ → la tonalità è La maggiore.',{kbd:K('F4','B4',{'G#4':'p','A4':'y'},{arcs:[['G#4','A4',['+1 semitone','+1 semitono'],1]]})}]];
C[13]=[
 ['Going the other way, a fifth lower each time, you get <b>flats</b>: F major has one flat (B♭), B♭ major two, E♭ major three, A♭ major four.','Andando nell’altro senso, una quinta più giù ogni volta, arrivano i <b>bemolli</b>: Fa maggiore ha un bemolle (Si♭), Si♭ maggiore due, Mi♭ maggiore tre, La♭ maggiore quattro.'],
 ['The flats arrive in the opposite order: <b>B, E, A, D, G, C, F</b> — the sharps read backwards.','I bemolli arrivano nell’ordine opposto: <b>Si, Mi, La, Re, Sol, Do, Fa</b> — i diesis letti al contrario.',{key:-4,cols:[]}],
 ['The trick to name the key: the <b>second-last flat</b> is the name of the key. B♭, E♭, A♭ → second-last is E♭: E♭ major. Only F major has one flat: just learn it by heart.','Il trucco per dare il nome: il <b>penultimo bemolle</b> è il nome della tonalità. Si♭, Mi♭, La♭ → il penultimo è Mi♭: Mi♭ maggiore. Solo Fa maggiore ha un bemolle: quella si impara a memoria.',{key:-3,cols:[]}]];
C[14]=[
 ['Let’s put it together. No sharps or flats: C major. Sharps: last sharp + one semitone. Flats: the second-last flat (and one flat = F).','Mettiamo tutto insieme. Niente diesis né bemolli: Do maggiore. Diesis: ultimo diesis + un semitono. Bemolli: il penultimo bemolle (e un bemolle = Fa).',{key:3,cols:[]}],
 ['Don’t worry about speed: look, apply the trick, answer. After a few tries your eyes will recognise them by themselves, like faces.','Non preoccuparti della velocità: guarda, applica il trucco, rispondi. Dopo qualche prova gli occhi le riconosceranno da soli, come le facce.']];
C[15]=[
 ['Each note of a scale is a <b>degree</b>: the first step, the second… we write them with Roman numerals, I to VII.','Ogni nota della scala è un <b>grado</b>: il primo gradino, il secondo… li scriviamo con i numeri romani, da I a VII.',{cols:['C4=I','D4=II','E4=III','F4=IV','G4=V','A4=VI','B4=VII']}],
 ['The first degree is the <b>tonic</b>: home, where the music rests. Play a scale and stop on the seventh step: you feel the need to go back to the tonic, don’t you?','Il primo grado è la <b>tonica</b>: casa, dove la musica riposa. Suona la scala e fermati al settimo gradino: senti il bisogno di tornare alla tonica, vero?',{cols:['C4|D4|E4|F4|G4|A4|B4']}],
 ['That seventh step is called the <b>leading note</b> (sensibile): it leads you home, just a semitone below the tonic.','Quel settimo gradino si chiama <b>sensibile</b>: ti accompagna a casa, a un solo semitono sotto la tonica.',{kbd:K('G4','C5',{'B4':'p','C5':'y'},{arcs:[['B4','C5',['home!','a casa!'],1]]}),cols:['B4|C5']}],
 ['The other important ones: the <b>dominant</b> (V), the strongest after the tonic, and the <b>subdominant</b> (IV). Their names: I tonic, II supertonic, III mediant, IV subdominant, V dominant, VI submediant, VII leading note.','Gli altri importanti: la <b>dominante</b> (V), la più forte dopo la tonica, e la <b>sottodominante</b> (IV). I nomi: I tonica, II sopratonica, III mediante, IV sottodominante, V dominante, VI sopradominante, VII sensibile.']];
C[16]=[
 ['Play the white keys again, but this time from A to A. Same keys as C major, but it sounds darker, more serious: this is <b>A minor</b>.','Suona di nuovo i tasti bianchi, ma questa volta da La a La. Stessi tasti di Do maggiore, ma suona più scuro, più serio: è <b>La minore</b>.',{kbd:K('A4','A5',{'A4':'y','B4':'y','C5':'y','D5':'y','E5':'y','F5':'y','G5':'y','A5':'y'}),cols:['A4|B4|C5|D5|E5|F5|G5|A5']}],
 ['A minor and C major share the same notes and the same key signature: they are “relatives”. A minor is the <b>relative minor</b> of C major.','La minore e Do maggiore hanno le stesse note e la stessa armatura: sono “parenti”. La minore è la <b>relativa minore</b> di Do maggiore.'],
 ['The trick to find it: from the major tonic, go <b>down 3 semitones</b> (a minor third). From C down 3: B, B♭, A → A minor. From G: F♯, F, E → E minor.','Il trucco per trovarla: dalla tonica maggiore scendi di <b>3 semitoni</b> (una terza minore). Da Do giù 3: Si, Si♭, La → La minore. Da Sol: Fa♯, Fa, Mi → Mi minore.',{kbd:K('G4','C5',{'C5':'y','A4':'p'},{top:{'B4':'1','A#4':'2','A4':'3'}})}]];
C[17]=[
 ['The <b>natural minor</b> scale is the one you just played: the notes of the relative major, starting from the 6th degree. Its recipe: T-S-T-T-S-T-T.','La scala <b>minore naturale</b> è quella che hai appena suonato: le note della relativa maggiore, partendo dal 6° grado. La sua ricetta: T-S-T-T-S-T-T.',{kbd:K('A4','A5',{'B4':'p','C5':'p','E5':'p','F5':'p'},{arcs:[['B4','C5',['S','S'],1],['E5','F5',['S','S'],1]]}),cols:['A4|B4|C5|D5|E5|F5|G5|A5']}],
 ['Why does it sound sadder? Its third step is close to the tonic: A to C is a <b>minor third</b> (3 semitones). In major, the third is bigger (4).','Perché suona più triste? Il suo terzo gradino è vicino alla tonica: da La a Do c’è una <b>terza minore</b> (3 semitoni). In maggiore la terza è più grande (4).',{cols:['A4 C5 E5=La m','C4 E4 G4=Do']}]];
C[18]=[
 ['In natural minor the 7th step is a whole tone below the tonic: G to A. Nothing pulls you home. So we often raise it by a semitone: G becomes <b>G♯</b>. Now it leads home again!','Nella minore naturale il 7° gradino sta un tono intero sotto la tonica: Sol–La. Niente ti tira verso casa. Così spesso lo alziamo di un semitono: il Sol diventa <b>Sol♯</b>. Ora torna a portarti a casa!',{kbd:K('E5','A5',{'G#5':'p','A5':'y'},{arcs:[['G#5','A5',['home!','a casa!'],1]]}),cols:['G5|A5','G#5|A5']}],
 ['The minor scale with the raised 7th is the <b>harmonic minor</b>. It sounds a bit exotic, because between F and G♯ there is a big jump.','La scala minore con il 7° alzato è la <b>minore armonica</b>. Suona un po’ esotica, perché tra Fa e Sol♯ c’è un salto grande.',{cols:['A4|B4|C5|D5|E5|F5|G#5|A5']}],
 ['To smooth that jump when the melody goes up, singers raise the 6th too: F♯ and G♯. This is the <b>melodic minor</b>. Going down, it goes back to natural.','Per ammorbidire quel salto quando la melodia sale, i cantanti alzano anche il 6°: Fa♯ e Sol♯. È la <b>minore melodica</b>. Scendendo, torna naturale.',{cols:['A4|B4|C5|D5|E5|F#5|G#5|A5']}]];
C[19]=[
 ['Keys are like towns: some are neighbours, others far away. Two keys are <b>close</b> when their key signatures differ by at most one sharp or flat.','Le tonalità sono come paesi: alcune sono vicine, altre lontane. Due tonalità sono <b>vicine</b> quando le loro armature differiscono al massimo di un diesis o un bemolle.'],
 ['C major’s neighbours: G major (one sharp), F major (one flat), and their relative minors: A minor, E minor, D minor. Music travels easily between neighbours, because they share many notes.','I vicini di Do maggiore: Sol maggiore (un diesis), Fa maggiore (un bemolle), e le loro relative minori: La minore, Mi minore, Re minore. La musica viaggia facilmente tra vicini, perché condividono molte note.']];
/* ======================= 3. TRIADS ======================= */
C[21]=[
 ['Until now we played one note at a time, like a melody. Now let’s press <b>several keys together</b>: the sound you get is a <b>chord</b>.','Finora abbiamo suonato una nota alla volta, come una melodia. Ora premiamo <b>più tasti insieme</b>: il suono che ottieni è un <b>accordo</b>.',{kbd:K('C4','C5',{'C4':'y','E4':'y','G4':'y'}),cols:['C4 E4 G4']}],
 ['Not every group of keys sounds nice. Press C, D and E together: it’s a little cluster that grates. Press C, E and G: round, sweet, stable. Why?','Non ogni gruppo di tasti suona bene. Premi Do, Re e Mi insieme: è un grappolino che stride. Premi Do, Mi e Sol: rotondo, dolce, stabile. Perché?',{cols:['C4 D4 E4','C4 E4 G4']}],
 ['The secret: the good chords are built by <b>skipping one white key each time</b>. C, (skip D), E, (skip F), G. Each jump is a <b>third</b>. Chords are “stacks of thirds”.','Il segreto: gli accordi belli si costruiscono <b>saltando un tasto bianco ogni volta</b>. Do, (salta il Re), Mi, (salta il Fa), Sol. Ogni salto è una <b>terza</b>. Gli accordi sono “pile di terze”.',{kbd:K('C4','C5',{'C4':'y','E4':'y','G4':'y','D4':'p','F4':'p'},{top:{'D4':'✗','F4':'✗'}}),cols:['C4 E4 G4','F4 A4 C5','G4 B4 D5']}]];
C[22]=[
 ['A chord of <b>three</b> notes stacked in thirds is a <b>triad</b> (tri = three). It’s the basic brick of harmony, like the atom in chemistry.','Un accordo di <b>tre</b> note impilate per terze è una <b>triade</b> (tri = tre). È il mattone di base dell’armonia, come l’atomo nella chimica.'],
 ['On the piano: put a finger on any white key, skip one, press the next, skip one, press the next. Thumb, middle finger, little finger: you are playing a triad!','Sul pianoforte: metti un dito su un tasto bianco qualsiasi, saltane uno, premi il successivo, saltane uno, premi il successivo. Pollice, medio, mignolo: stai suonando una triade!',{kbd:K('C4','C5',{'D4':'y','F4':'y','A4':'y'}),cols:['D4 F4 A4']}],
 ['On the staff a triad looks like a little <b>snowman</b>: three notes all on lines, or all in spaces, one on top of the other.','Sul pentagramma una triade sembra un piccolo <b>pupazzo di neve</b>: tre note tutte sulle righe, o tutte negli spazi, una sopra l’altra.',{cols:['E4 G4 B4','F4 A4 C5','D4 F4 A4']}]];
C[23]=[
 ['Each note of the triad has a name. The bottom one, where you started, is the <b>root</b>: it gives the chord its name. C–E–G is the chord of C.','Ogni nota della triade ha un nome. Quella in basso, da cui sei partito, è la <b>fondamentale</b>: dà il nome all’accordo. Do–Mi–Sol è l’accordo di Do.',{kbd:K('C4','C5',{'C4':'y','E4':'g','G4':'b'},{top:{'C4':'1','E4':'3','G4':'5'}}),cols:['C4 E4 G4']}],
 ['The middle one is the <b>third</b> (it is a third above the root), the top one is the <b>fifth</b> (a fifth above the root). Root, third, fifth: like 1, 3 and 5 of the scale.','Quella in mezzo è la <b>terza</b> (sta una terza sopra la fondamentale), quella in alto è la <b>quinta</b> (una quinta sopra la fondamentale). Fondamentale, terza, quinta: come 1, 3 e 5 della scala.'],
 ['Think of a family photo: the root is the grandparent who gives the surname, the third and the fifth are standing on top.','Pensa a una foto di famiglia: la fondamentale è il nonno che dà il cognome, la terza e la quinta stanno sopra di lui.']];
C[24]=[
 ['Now the colour. Count the semitones of the two floors of the snowman. C to E: 4 semitones (a major third). E to G: 3 semitones (a minor third).','Ora il colore. Conta i semitoni dei due piani del pupazzo. Da Do a Mi: 4 semitoni (terza maggiore). Da Mi a Sol: 3 semitoni (terza minore).',{kbd:K('C4','C5',{'C4':'y','E4':'y','G4':'y'},{arcs:[['C4','E4',['4','4'],0],['E4','G4',['3','3'],0]]}),cols:['C4 E4 G4']}],
 ['<b>4 below, 3 on top</b>: this is the recipe of the <b>major triad</b>. It sounds bright and happy. C major, F major, G major are all made this way.','<b>4 sotto, 3 sopra</b>: è la ricetta della <b>triade maggiore</b>. Suona luminosa e allegra. Do maggiore, Fa maggiore, Sol maggiore sono fatti tutti così.',{cols:['C4 E4 G4=Do','F4 A4 C5=Fa','G4 B4 D5=Sol']}],
 ['With the recipe you can build a major triad on any key, even a black one: count 4 semitones up, then 3 more. From D: D, F♯, A.','Con la ricetta puoi costruire una triade maggiore su qualsiasi tasto, anche nero: conta 4 semitoni su, poi altri 3. Dal Re: Re, Fa♯, La.',{kbd:K('C4','C5',{'D4':'y','F#4':'y','A4':'y'}),cols:['D4 F#4 A4']}]];
C[25]=[
 ['Swap the two floors: <b>3 below, 4 on top</b>. This is the <b>minor triad</b>: darker, more melancholic. A–C–E is A minor.','Scambia i due piani: <b>3 sotto, 4 sopra</b>. È la <b>triade minore</b>: più scura, più malinconica. La–Do–Mi è La minore.',{kbd:K('G4','G5',{'A4':'y','C5':'y','E5':'y'},{arcs:[['A4','C5',['3','3'],0],['C5','E5',['4','4'],0]]}),cols:['A4 C5 E5']}],
 ['Try it: play C–E–G (major), then lower the middle note by one semitone: C–E♭–G (minor). Only one key moved, and the mood changes completely!','Prova: suona Do–Mi–Sol (maggiore), poi abbassa la nota di mezzo di un semitono: Do–Mi♭–Sol (minore). Si è spostato un solo tasto, e l’atmosfera cambia del tutto!',{kbd:K('C4','C5',{'C4':'y','D#4':'p','G4':'y','E4':'g'}),cols:['C4 E4 G4','C4 Eb4 G4']}],
 ['In both major and minor, the bottom and top notes are a <b>perfect fifth</b> apart (7 semitones). Only the middle note decides happy or sad.','Sia in maggiore sia in minore, la nota sotto e quella sopra sono a distanza di <b>quinta giusta</b> (7 semitoni). Solo la nota di mezzo decide se allegro o triste.']];
C[26]=[
 ['Two small floors: <b>3 and 3</b>. The top note is now closer than a fifth: the <b>diminished triad</b>. B–D–F is the one you find on the white keys.','Due piani piccoli: <b>3 e 3</b>. La nota in alto ora è più vicina di una quinta: la <b>triade diminuita</b>. Si–Re–Fa è quella che trovi sui tasti bianchi.',{kbd:K('A4','A5',{'B4':'y','D5':'y','F5':'y'},{arcs:[['B4','D5',['3','3'],0],['D5','F5',['3','3'],0]]}),cols:['B4 D5 F5']}],
 ['It sounds tense, a bit scary, like the music of a thriller: it doesn’t want to stay, it wants to move. We write it with a small circle: <b>B°</b>.','Suona tesa, un po’ paurosa, come la musica di un giallo: non vuole restare ferma, vuole muoversi. La scriviamo con un cerchietto: <b>Si°</b>.']];
C[27]=[
 ['Two big floors: <b>4 and 4</b>. The top note is pushed further than a fifth: the <b>augmented triad</b>. C–E–G♯.','Due piani grandi: <b>4 e 4</b>. La nota in alto è spinta oltre la quinta: la <b>triade eccedente</b>. Do–Mi–Sol♯.',{kbd:K('C4','C5',{'C4':'y','E4':'y','G#4':'y'},{arcs:[['C4','E4',['4','4'],0],['E4','G#4',['4','4'],0]]}),cols:['C4 E4 G#4']}],
 ['It sounds dreamy and suspended, like a question with no answer. We write it with a plus: <b>C+</b>. It’s the rarest of the four.','Suona sognante e sospesa, come una domanda senza risposta. La scriviamo con un più: <b>Do+</b>. È la più rara delle quattro.']];
C[28]=[
 ['Here is the whole family. Count the two floors, bottom first:','Ecco tutta la famiglia. Conta i due piani, prima quello sotto:',{cols:['C4 E4 G4=M','C4 Eb4 G4=m','C4 Eb4 Gb4=°','C4 E4 G#4=+']}],
 ['<b>4+3 = major</b> (happy) · <b>3+4 = minor</b> (sad) · <b>3+3 = diminished</b> (tense) · <b>4+4 = augmented</b> (dreamy). Four recipes, that’s all.','<b>4+3 = maggiore</b> (allegra) · <b>3+4 = minore</b> (triste) · <b>3+3 = diminuita</b> (tesa) · <b>4+4 = eccedente</b> (sognante). Quattro ricette, tutto qui.'],
 ['On the white keys there is a shortcut: a chord whose root is C, F or G is major; D, E or A is minor; B is diminished. Augmented never happens with white keys only.','Sui tasti bianchi c’è una scorciatoia: un accordo con fondamentale Do, Fa o Sol è maggiore; Re, Mi o La è minore; Si è diminuito. L’eccedente con i soli tasti bianchi non capita mai.']];
C[29]=[
 ['Build a triad on every step of the C major scale, using only white keys. You get seven chords, one per degree.','Costruisci una triade su ogni gradino della scala di Do maggiore, usando solo i tasti bianchi. Ottieni sette accordi, uno per grado.',{cols:['C4 E4 G4=I','D4 F4 A4=ii','E4 G4 B4=iii','F4 A4 C5=IV','G4 B4 D5=V','A4 C5 E5=vi','B4 D5 F5=vii°']}],
 ['The pattern is always the same in every major key: <b>I, IV, V major</b>; <b>ii, iii, vi minor</b>; <b>vii diminished</b>. Remember “1-4-5 happy, 2-3-6 sad, 7 tense”.','Lo schema è sempre lo stesso in ogni tonalità maggiore: <b>I, IV, V maggiori</b>; <b>ii, iii, vi minori</b>; <b>vii diminuito</b>. Ricorda “1-4-5 allegri, 2-3-6 tristi, 7 teso”.'],
 ['I, IV and V are the three pillars: with just these three chords you can accompany thousands of songs.','I, IV e V sono i tre pilastri: con questi tre accordi soltanto si accompagnano migliaia di canzoni.',{cols:['C4 E4 G4=I','F4 A4 C5=IV','G4 B4 D5=V','C4 E4 G4=I']}]];
C[30]=[
 ['Musicians use two ways to name chords. The first: <b>Roman numerals</b>, which tell the degree. CAPITAL for major (I, IV, V), small for minor (ii, vi), small with ° for diminished (vii°).','I musicisti usano due modi per chiamare gli accordi. Il primo: i <b>numeri romani</b>, che dicono il grado. MAIUSCOLO per i maggiori (I, IV, V), minuscolo per i minori (ii, vi), minuscolo con ° per il diminuito (vii°).'],
 ['The second: <b>chord symbols</b>, which tell the root with its letter: C = C major, Am = A minor, B° = B diminished. Guitarists use them a lot (C = Do, D = Re, E = Mi, F = Fa, G = Sol, A = La, B = Si).','Il secondo: le <b>sigle</b>, che dicono la fondamentale con la sua lettera: C = Do maggiore, Am = La minore, B° = Si diminuito. I chitarristi le usano tantissimo (C = Do, D = Re, E = Mi, F = Fa, G = Sol, A = La, B = Si).'],
 ['They are two points of view on the same chord: the numeral says <b>what job</b> it does in the key; the symbol says <b>which notes</b> it has. In G major, D is the V.','Sono due punti di vista sullo stesso accordo: il numero romano dice <b>che lavoro</b> fa nella tonalità; la sigla dice <b>che note</b> ha. In Sol maggiore, D (Re) è il V.',{key:1,cols:['G4 B4 D5=I · G','A4 C5 E5=ii · Am','D4 F#4 A4=V · D']}]];
C[31]=[
 ['In a minor key we use the harmonic minor, with the raised 7th step (G♯ in A minor). Why? Because it turns the V chord into a major chord: E–G♯–B, which pulls home strongly.','In una tonalità minore usiamo la minore armonica, con il 7° gradino alzato (Sol♯ in La minore). Perché? Perché trasforma l’accordo di V in maggiore: Mi–Sol♯–Si, che tira forte verso casa.',{cols:['A4 C5 E5=i','D4 F4 A4=iv','E4 G#4 B4=V']}],
 ['So in minor: <b>i and iv minor</b>, <b>V major</b>, <b>VI major</b>, ii° and vii° diminished. The tonic chord is minor, but the dominant is major: that’s the secret of minor music.','Quindi in minore: <b>i e iv minori</b>, <b>V maggiore</b>, <b>VI maggiore</b>, ii° e vii° diminuiti. L’accordo di tonica è minore, ma la dominante è maggiore: è il segreto della musica in minore.']];
/* ======================= 4. INVERSIONS AND FIGURES ======================= */
C[33]=[
 ['Take the C chord: C–E–G. Now move the C up an octave: E–G–C. Same three notes, the same chord… but the lowest note is now E.','Prendi l’accordo di Do: Do–Mi–Sol. Ora sposta il Do su di un’ottava: Mi–Sol–Do. Stesse tre note, lo stesso accordo… ma la nota più bassa ora è il Mi.',{kbd:K('C4','C5',{'E4':'y','G4':'y','C5':'y','C4':'g'},{arcs:[['C4','C5',['the C goes up','il Do sale'],1]]}),cols:['C4 E4 G4','E4 G4 C5']}],
 ['Two different words: the <b>bass</b> is simply the lowest note you hear. The <b>root</b> is the note the chord is built on (its “surname”). In E–G–C the bass is E, but the root is still C.','Due parole diverse: il <b>basso</b> è semplicemente la nota più grave che senti. La <b>fondamentale</b> è la nota su cui l’accordo è costruito (il suo “cognome”). In Mi–Sol–Do il basso è Mi, ma la fondamentale resta Do.'],
 ['Like a family photo where the grandparent sits on the side instead of in the middle: he is still the grandparent.','Come una foto di famiglia in cui il nonno si siede di lato invece che al centro: resta sempre il nonno.']];
C[34]=[
 ['When the root is at the bottom, the chord is in <b>root position</b>: the most solid and stable way to play it.','Quando la fondamentale è in basso, l’accordo è in <b>stato fondamentale</b>: il modo più solido e stabile di suonarlo.',{cols:['C4 E4 G4','F4 A4 C5']}],
 ['Musicians describe chords by counting up from the bass. Above C there is a 3rd (E) and a 5th (G): so root position is written <b>5/3</b>. Usually we don’t even write it: no numbers = 5/3.','I musicisti descrivono gli accordi contando dal basso in su. Sopra il Do c’è una 3ª (Mi) e una 5ª (Sol): per questo lo stato fondamentale si scrive <b>5/3</b>. Di solito non lo si scrive nemmeno: nessun numero = 5/3.']];
C[35]=[
 ['When the <b>third</b> is at the bottom (E–G–C) the chord is in <b>first inversion</b>. It sounds lighter, less “planted” on the ground.','Quando in basso c’è la <b>terza</b> (Mi–Sol–Do) l’accordo è in <b>primo rivolto</b>. Suona più leggero, meno “piantato” per terra.',{cols:['C4 E4 G4','E4 G4 C5']}],
 ['Count from the bass E: G is a 3rd above, C is a <b>6th</b> above. We write just <b>6</b>.','Conta dal basso Mi: il Sol sta una 3ª sopra, il Do una <b>6ª</b> sopra. Scriviamo solo <b>6</b>.',{kbd:K('D4','D5',{'E4':'y','G4':'y','C5':'y'},{top:{'E4':'1','G4':'3','C5':'6'}})}]];
C[36]=[
 ['When the <b>fifth</b> is at the bottom (G–C–E) the chord is in <b>second inversion</b>. It sounds unstable, as if it were floating.','Quando in basso c’è la <b>quinta</b> (Sol–Do–Mi) l’accordo è in <b>secondo rivolto</b>. Suona instabile, come se galleggiasse.',{cols:['G4 C5 E5']}],
 ['From the bass G: C is a 4th above, E a 6th above. We write <b>6/4</b>. It’s a delicate chord: later you’ll learn the few places where it can be used.','Dal basso Sol: il Do sta una 4ª sopra, il Mi una 6ª sopra. Scriviamo <b>6/4</b>. È un accordo delicato: più avanti vedremo i pochi posti dove si può usare.']];
C[37]=[
 ['The numbers under the bass are called <b>figures</b> (numerica). They are a shorthand: they tell which intervals to play above the bass note.','I numeri sotto il basso si chiamano <b>numerica</b>. Sono una stenografia: dicono quali intervalli suonare sopra la nota di basso.',{cols:['C4 E4 G4=5/3','E4 G4 C5=6','G4 C5 E5=6/4']}],
 ['Three cases to remember: <b>nothing (5/3)</b> = root at the bottom; <b>6</b> = third at the bottom; <b>6/4</b> = fifth at the bottom. A little rhyme: “nothing, six, six-four: root, third, fifth on the floor”.','Tre casi da ricordare: <b>niente (5/3)</b> = fondamentale sotto; <b>6</b> = terza sotto; <b>6/4</b> = quinta sotto. In ordine: niente, sei, sei-quattro — fondamentale, terza, quinta.']];
C[38]=[
 ['Chord symbols have their own way to show the bass: a <b>slash</b>. C/E means “C chord, with E in the bass”: a first inversion.','Le sigle hanno il loro modo di mostrare il basso: la <b>barra</b>. C/E vuol dire “accordo di Do, con il Mi al basso”: un primo rivolto.',{cols:['E4 G4 C5=C/E','D4 G4 B4=G/D']}],
 ['Read it like a fraction: the chord on top, the bass below. G/D = G chord over D = second inversion.','Leggila come una frazione: sopra l’accordo, sotto il basso. G/D = accordo di Sol sopra il Re = secondo rivolto.']];
C[39]=[
 ['In real music the notes of a chord are often spread out, in different octaves. How do you find the root? Put the notes back in order, as close as possible, <b>stacked in thirds</b>.','Nella musica vera le note di un accordo sono spesso sparse, in ottave diverse. Come trovi la fondamentale? Rimetti le note in fila, il più vicine possibile, <b>impilate per terze</b>.',{cols:['E4 C5 G5','C4 E4 G4']}],
 ['The note at the bottom of the snowman is the root. E, C, G → C–E–G → root C. It works like a puzzle: there is only one way the pieces fit in thirds.','La nota in fondo al pupazzo di neve è la fondamentale. Mi, Do, Sol → Do–Mi–Sol → fondamentale Do. Funziona come un puzzle: c’è un solo modo in cui i pezzi si incastrano per terze.']];
C[40]=[
 ['Two steps, always in this order. <b>1)</b> Find the root (stack the notes in thirds). <b>2)</b> Look at the lowest note.','Due passi, sempre in quest’ordine. <b>1)</b> Trova la fondamentale (impila le note per terze). <b>2)</b> Guarda la nota più bassa.'],
 ['Root in the bass → root position (5/3). Third in the bass → first inversion (6). Fifth in the bass → second inversion (6/4).','Fondamentale al basso → stato fondamentale (5/3). Terza al basso → primo rivolto (6). Quinta al basso → secondo rivolto (6/4).',{cols:['C4 E4 G4=5/3','E4 G4 C5=6','G4 C5 E5=6/4']}]];
C[41]=[
 ['A little of everything: roots, inversions, figures, chord symbols. Go calmly: for each chord, first the root, then the bass.','Un po’ di tutto: fondamentali, rivolti, numerica, sigle. Vai con calma: per ogni accordo, prima la fondamentale, poi il basso.']];
/* ======================= 5. WRITING IN FOUR VOICES ======================= */
C[43]=[
 ['Now imagine a little choir of four singers. Each one sings one note of the chord. From high to low: <b>soprano</b>, <b>alto</b>, <b>tenor</b>, <b>bass</b>.','Ora immagina un piccolo coro di quattro cantanti. Ognuno canta una nota dell’accordo. Dall’acuto al grave: <b>soprano</b>, <b>contralto</b>, <b>tenore</b>, <b>basso</b>.',{clef:'g',cols:['C3_b G3_b E4_t C5_t']}],
 ['We write them on two staves joined together: soprano and alto on the top one (treble clef), tenor and bass on the bottom one (bass clef). It’s the classic way to study harmony, the same used in the Cadences game.','Li scriviamo su due pentagrammi uniti: soprano e contralto su quello in alto (chiave di violino), tenore e basso su quello in basso (chiave di basso). È il modo classico di studiare l’armonia, lo stesso del gioco delle Cadenze.'],
 ['Each voice can sing only in its own zone, its <b>range</b>: roughly soprano C4–G5, alto G3–D5, tenor C3–G4, bass E2–C4. Too high or too low, and the singer can’t make it!','Ogni voce può cantare solo nella sua zona, la sua <b>estensione</b>: più o meno soprano Do4–Sol5, contralto Sol3–Re5, tenore Do3–Sol4, basso Mi2–Do4. Troppo in alto o troppo in basso, e il cantante non ci arriva!']];
C[44]=[
 ['The singers must stay close enough to sound like one choir. Rule: between soprano and alto, and between alto and tenor, never more than an <b>octave</b>.','I cantanti devono restare abbastanza vicini per suonare come un coro solo. Regola: tra soprano e contralto, e tra contralto e tenore, mai più di un’<b>ottava</b>.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=ok','C3_b C3_b E4_t C5_t=⚠']}],
 ['Only the bass may go further from the tenor: it’s the foundation, it can stay down below.','Solo il basso può allontanarsi di più dal tenore: è la fondamenta, può restare giù in basso.']];
C[45]=[
 ['Each singer keeps their place in the line: the alto never goes below the tenor, the tenor never above the alto. If they swap, it’s a <b>crossing</b>, and the listener gets confused about who is singing what.','Ogni cantante tiene il suo posto nella fila: il contralto non scende mai sotto il tenore, il tenore non sale mai sopra il contralto. Se si scambiano è un <b>incrocio</b>, e chi ascolta non capisce più chi canta cosa.'],
 ['Think of four cars on a four-lane road: each one stays in its lane.','Pensa a quattro auto su una strada a quattro corsie: ognuna resta nella sua corsia.']];
C[46]=[
 ['The three upper voices can be close together or spread out. <b>Close position</b>: soprano, alto and tenor as close as possible; no chord note would fit between them.','Le tre voci superiori possono stare vicine o larghe. <b>Posizione stretta</b>: soprano, contralto e tenore il più vicini possibile; tra loro non entrerebbe nessuna nota dell’accordo.',{clef:'g',cols:['C3_b C4_b E4_t G4_t=stretta']}],
 ['<b>Open position</b>: a gap where another chord note could fit. Both are fine: choose the one that lets the voices move less.','<b>Posizione lata</b>: c’è un buco dove entrerebbe un’altra nota dell’accordo. Vanno bene tutte e due: scegli quella che fa muovere meno le voci.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=lata']}]];
C[47]=[
 ['A triad has three notes, but we have four singers. One note must be sung by two of them: we <b>double</b> it.','Una triade ha tre note, ma i cantanti sono quattro. Una nota deve essere cantata da due di loro: la <b>raddoppiamo</b>.'],
 ['In root position, double the <b>root</b>: it’s the most solid note, like adding a second column under a roof. C–E–G becomes C–G–C–E.','In stato fondamentale si raddoppia la <b>fondamentale</b>: è la nota più solida, come aggiungere una seconda colonna sotto un tetto. Do–Mi–Sol diventa Do–Sol–Do–Mi.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=Do Do']}],
 ['Never double the <b>leading note</b> (the 7th step): it has a precise job, going up to the tonic. Two singers doing it together would make a mess.','Non raddoppiare mai la <b>sensibile</b> (il 7° gradino): ha un compito preciso, salire alla tonica. Due cantanti che lo fanno insieme combinerebbero un pasticcio.']];
C[48]=[
 ['A recipe to build a chord from the bass note: <b>1)</b> find which chord it is; <b>2)</b> double the root; <b>3)</b> put the other three notes close together above, each voice in its range.','Una ricetta per costruire un accordo dalla nota di basso: <b>1)</b> trova di che accordo si tratta; <b>2)</b> raddoppia la fondamentale; <b>3)</b> metti le altre tre note vicine sopra, ogni voce nella sua estensione.'],
 ['Don’t look for the “most beautiful” solution: look for the <b>simplest</b> one. In harmony, simple is beautiful.','Non cercare la soluzione “più bella”: cerca la <b>più semplice</b>. In armonia, semplice è bello.']];
C[49]=[
 ['When the choir goes from one chord to the next, each voice moves. Two voices can move in the <b>same direction</b> (similar motion), in <b>opposite directions</b> (contrary motion), or one stays still while the other moves (<b>oblique</b> motion).','Quando il coro passa da un accordo al successivo, ogni voce si muove. Due voci possono muoversi nella <b>stessa direzione</b> (moto retto), in <b>direzioni opposte</b> (moto contrario), oppure una resta ferma e l’altra si muove (moto <b>obliquo</b>).'],
 ['Contrary motion between bass and soprano is the safest: like two dancers moving apart and together, they never get in each other’s way.','Il moto contrario tra basso e soprano è il più sicuro: come due ballerini che si allontanano e si avvicinano, non si pestano mai i piedi.']];
C[50]=[
 ['The most famous rule of harmony: no <b>parallel fifths</b> or <b>octaves</b>. If two voices are a fifth apart and move together to another fifth, they stop sounding like two voices and melt into one.','La regola più famosa dell’armonia: niente <b>quinte</b> né <b>ottave parallele</b>. Se due voci sono a distanza di quinta e si muovono insieme verso un’altra quinta, smettono di sembrare due voci e si fondono in una.',{clef:'g',cols:['C3_b G3_b E4_t C5_t','D3_b A3_b F4_t D5_t=⚠']}],
 ['How to spot them: look at each pair of voices. Fifth → fifth, or octave → octave, moving in the same direction = forbidden. Fifth → something else = all good.','Come accorgersene: guarda ogni coppia di voci. Quinta → quinta, oppure ottava → ottava, muovendosi nella stessa direzione = vietato. Quinta → qualcos’altro = tutto bene.'],
 ['The easy cure: move the upper voices in <b>contrary motion</b> to the bass.','La cura facile: muovi le voci superiori in <b>moto contrario</b> rispetto al basso.']];
C[51]=[
 ['A sneakier relative: when soprano and bass arrive on a fifth or octave <b>both moving the same way</b>, with the soprano leaping, we hear “hidden” fifths or octaves. Avoid them too.','Un parente più subdolo: quando soprano e basso arrivano su una quinta o un’ottava <b>muovendosi nella stessa direzione</b>, con il soprano che salta, si sentono quinte od ottave “nascoste”. Evitale anche loro.'],
 ['But if the soprano moves by a small step, they are allowed: the step hides the problem.','Ma se il soprano si muove di un passo piccolo, sono permesse: il passettino nasconde il problema.']];
C[52]=[
 ['When two chords have a note in common, let the same singer <b>keep it</b>. It’s the smoothest connection: like walking from one room to another through a door that’s already open.','Quando due accordi hanno una nota in comune, lascia che lo stesso cantante la <b>tenga</b>. È il collegamento più morbido: come passare da una stanza all’altra da una porta già aperta.',{clef:'g',cols:['C3_b G3_b C4_b E4_t','F3_b A3_b C4_b F4_t']}]];
C[53]=[
 ['The other voices go to the <b>nearest</b> note of the new chord. Small steps, few leaps: singers are lazy, and they sing better that way!','Le altre voci vanno sulla nota <b>più vicina</b> del nuovo accordo. Passi piccoli, pochi salti: i cantanti sono pigri, e così cantano meglio!'],
 ['The bass is the exception: it can leap, because it carries the roots of the chords.','Il basso fa eccezione: può saltare, perché porta le fondamentali degli accordi.']];
C[54]=[
 ['Remember the leading note, the step just below the tonic? Like a magnet, it is pulled up to the tonic. From V to I, the voice that has it <b>goes up a semitone</b>.','Ricordi la sensibile, il gradino subito sotto la tonica? Come una calamita, è attratta verso l’alto, verso la tonica. Da V a I, la voce che ce l’ha <b>sale di un semitono</b>.',{clef:'g',cols:['G2_b D4_b G4_t B4_t','C3_b E4_t G4_t C5_t']}],
 ['In C major: B goes to C. Always. It’s one of the few “always” of harmony.','In Do maggiore: il Si va al Do. Sempre. È uno dei pochi “sempre” dell’armonia.',{kbd:K('G4','C5',{'B4':'p','C5':'y'},{arcs:[['B4','C5',['up!','su!'],1]]})}]];
C[55]=[
 ['I and IV share the tonic (C is in both C–E–G and F–A–C). I and V share the dominant (G is in C–E–G and G–B–D).','I e IV hanno in comune la tonica (il Do sta sia in Do–Mi–Sol sia in Fa–La–Do). I e V hanno in comune la dominante (il Sol sta in Do–Mi–Sol e in Sol–Si–Re).'],
 ['So the recipe is: keep the common note in the same voice, and move the others by step to the nearest notes.','Quindi la ricetta è: tieni la nota comune nella stessa voce, e muovi le altre di grado sulle note più vicine.']];
C[56]=[
 ['IV and V have no notes in common (F–A–C and G–B–D). The bass goes up one step, from F to G.','IV e V non hanno note in comune (Fa–La–Do e Sol–Si–Re). Il basso sale di un gradino, da Fa a Sol.'],
 ['The trick: move the three upper voices <b>down</b>, each to the nearest note. Bass up, the others down: contrary motion, and no parallel fifths.','Il trucco: muovi le tre voci superiori <b>verso il basso</b>, ognuna sulla nota più vicina. Basso su, gli altri giù: moto contrario, e niente quinte parallele.',{clef:'g',cols:['F2_b F3_b A3_b C4_t','G2_b D3_b G3_b B3_t']}]];
C[57]=[
 ['Now you are the teacher. Look at an exercise and hunt for mistakes, in this order: ranges, distances between voices, crossings, parallel fifths and octaves.','Ora il maestro sei tu. Guarda un esercizio e cerca gli errori, in quest’ordine: estensioni, distanze tra le voci, incroci, quinte e ottave parallele.']];
/* ======================= 6. HARMONIC FUNCTIONS ======================= */
C[59]=[
 ['Chords are like characters in a story. Each one has a role. The <b>tonic</b> (I) is home: calm, rest, the end of the journey.','Gli accordi sono come i personaggi di una storia. Ognuno ha un ruolo. La <b>tonica</b> (I) è casa: calma, riposo, la fine del viaggio.',{cols:['C4 E4 G4=T']}],
 ['The <b>dominant</b> (V) is tension: it wants to go home, now. Play V and stop: you feel something is missing.','La <b>dominante</b> (V) è tensione: vuole tornare a casa, subito. Suona V e fermati: senti che manca qualcosa.',{cols:['C4 E4 G4','G4 B4 D5']}],
 ['The <b>subdominant</b> (IV) is setting off: it moves us away from home and prepares the dominant. Home → off we go → tension → home: T, S, D, T. Almost all music tells this little story.','La <b>sottodominante</b> (IV) è la partenza: ci allontana da casa e prepara la dominante. Casa → si parte → tensione → casa: T, S, D, T. Quasi tutta la musica racconta questa piccola storia.',{cols:['C4 E4 G4=T','F4 A4 C5=S','G4 B4 D5=D','C4 E4 G4=T']}]];
C[60]=[
 ['The other chords belong to one of these three families, like cousins. They share notes with the head of the family, so they can take its place.','Gli altri accordi appartengono a una di queste tre famiglie, come cugini. Condividono note con il capofamiglia, quindi possono prendere il suo posto.'],
 ['Tonic family: <b>I, vi, iii</b> (calm). Subdominant family: <b>IV, ii</b> (setting off). Dominant family: <b>V, vii°</b> (tension).','Famiglia della tonica: <b>I, vi, iii</b> (calma). Famiglia della sottodominante: <b>IV, ii</b> (partenza). Famiglia della dominante: <b>V, vii°</b> (tensione).',{cols:['C4 E4 G4=I','A4 C5 E5=vi','F4 A4 C5=IV','D4 F4 A4=ii','G4 B4 D5=V','B4 D5 F5=vii°']}]];
C[61]=[
 ['The strongest move between chords: the root goes <b>down a fifth</b> (or up a fourth, which on the keyboard lands on the same note name). G → C: V → I.','Il movimento più forte tra gli accordi: la fondamentale scende di <b>quinta</b> (o sale di quarta, che sulla tastiera arriva sullo stesso nome di nota). Sol → Do: V → I.'],
 ['Chain them and you get a falling ladder of fifths: vi → ii → V → I. Many songs are built on it: it sounds “inevitable”, every chord pulls the next one.','Mettili in fila e ottieni una scala di quinte che scende: vi → ii → V → I. Moltissime canzoni sono costruite così: suona “inevitabile”, ogni accordo tira il successivo.',{cols:['A4 C5 E5=vi','D4 F4 A4=ii','G4 B4 D5=V','C4 E4 G4=I']}]];
C[62]=[
 ['With chords in root position, the bass sings the roots, so it often <b>leaps</b> by a fourth or a fifth: C → F, G → C. The bass carries the harmony on its shoulders.','Con gli accordi in stato fondamentale, il basso canta le fondamentali, quindi spesso <b>salta</b> di quarta o di quinta: Do → Fa, Sol → Do. Il basso porta l’armonia sulle spalle.']];
C[63]=[
 ['Music speaks in <b>phrases</b>, like sentences. A phrase starts at home (the tonic), goes for a walk, and then stops: that stop is called a <b>cadence</b>.','La musica parla per <b>frasi</b>, come le frasi di un discorso. Una frase parte da casa (la tonica), fa una passeggiata, e poi si ferma: quella fermata si chiama <b>cadenza</b>.'],
 ['Cadences are the punctuation of music: some are a full stop, others a comma or a question mark. Sing “Happy birthday”: at the end of each line you can hear where it breathes.','Le cadenze sono la punteggiatura della musica: alcune sono un punto, altre una virgola o un punto di domanda. Canta “Tanti auguri a te”: alla fine di ogni verso senti dove prende fiato.']];
C[64]=[
 ['How often the chords change is the <b>harmonic rhythm</b>. Sometimes one chord lasts a whole bar, sometimes they change on every beat.','Quanto spesso cambiano gli accordi è il <b>ritmo armonico</b>. A volte un accordo dura una battuta intera, a volte cambia su ogni tempo.'],
 ['Usually the chords change faster near the end of the phrase, as if the music started to run towards the finish line.','Di solito gli accordi cambiano più in fretta verso la fine della frase, come se la musica cominciasse a correre verso il traguardo.']];
C[65]=[
 ['Given a bass line, which chords go above? If the bass note is the 1st step, try I; the 4th step, IV; the 5th step, V. The bass tells you the root.','Data una linea di basso, quali accordi ci vanno sopra? Se la nota di basso è il 1° gradino, prova I; il 4°, IV; il 5°, V. Il basso ti dice la fondamentale.'],
 ['Then complete the upper voices with the usual recipe: double the root, keep common notes, move by step.','Poi completa le voci superiori con la solita ricetta: raddoppia la fondamentale, tieni le note comuni, muovi di grado.']];
C[66]=[
 ['Now the opposite: a melody is given, you choose the chords. Each melody note belongs to several chords: C is in C–E–G (I), F–A–C (IV) and A–C–E (vi).','Ora il contrario: è data una melodia, tu scegli gli accordi. Ogni nota della melodia appartiene a più accordi: il Do sta in Do–Mi–Sol (I), Fa–La–Do (IV) e La–Do–Mi (vi).',{cols:['C4 E4 G4=I','F4 A4 C5=IV','A4 C5 E5=vi']}],
 ['How to choose? Think of the little story T–S–D–T: pick the chord that leads naturally to the next one, and save V–I for the end.','Come scegliere? Pensa alla piccola storia T–S–D–T: scegli l’accordo che porta in modo naturale al successivo, e tieni V–I per la fine.']];
C[67]=[
 ['A bit of everything: families, chains of fifths, connections. Remember the story: home, setting off, tension, home.','Un po’ di tutto: famiglie, catene di quinte, collegamenti. Ricorda la storia: casa, partenza, tensione, casa.']];
/* ======================= 7. CADENCES, PART ONE ======================= */
C[69]=[
 ['A <b>cadence</b> is the pair of chords that closes a phrase: the last two words of the musical sentence.','Una <b>cadenza</b> è la coppia di accordi che chiude una frase: le ultime due parole della frase musicale.'],
 ['Some cadences close completely, like a full stop. Others leave the question open, like a comma or a question mark. Learning them means learning to “read” where the music breathes.','Alcune cadenze chiudono del tutto, come un punto fermo. Altre lasciano la domanda aperta, come una virgola o un punto di domanda. Impararle vuol dire imparare a “leggere” dove la musica respira.']];
C[70]=[
 ['The strongest ending: <b>V → I</b>, both in root position, with the tonic in the soprano at the end. This is the <b>perfect cadence</b>: the full stop.','Il finale più forte: <b>V → I</b>, entrambi in stato fondamentale, con la tonica al soprano alla fine. È la <b>cadenza perfetta</b>: il punto fermo.',{clef:'g',cols:['G2_b D4_b G4_t B4_t=V','C3_b E4_t G4_t C5_t=I']}],
 ['Listen: after the V you hold your breath; on the I everything relaxes. It’s the “THE END” of a film.','Ascolta: dopo il V trattieni il respiro; sul I tutto si rilassa. È la scritta “FINE” di un film.']];
C[71]=[
 ['How each singer moves in V → I: the <b>bass</b> leaps from the 5th step to the 1st (G → C); the <b>leading note</b> rises to the tonic (B → C); the others go to the nearest notes.','Come si muove ogni cantante in V → I: il <b>basso</b> salta dal 5° al 1° gradino (Sol → Do); la <b>sensibile</b> sale alla tonica (Si → Do); gli altri vanno sulle note più vicine.',{clef:'g',cols:['G2_b D4_b G4_t B4_t=V','C3_b E4_t G4_t C5_t=I']}]];
C[72]=[
 ['Still V → I, but weaker: the soprano doesn’t end on the tonic, or one of the chords is inverted. This is the <b>imperfect cadence</b>: it closes, but like a semicolon rather than a full stop.','Sempre V → I, ma più debole: il soprano non finisce sulla tonica, oppure uno dei due accordi è rivoltato. È la <b>cadenza imperfetta</b>: chiude, ma come un punto e virgola invece di un punto.',{clef:'g',cols:['G2_b B3_b D4_t G4_t=V','C3_b C4_b E4_t G4_t=I']}]];
C[73]=[
 ['<b>IV → I</b>: the <b>plagal cadence</b>. Soft and gentle, with no leading note pulling. It is the “A-men” sung at the end of hymns.','<b>IV → I</b>: la <b>cadenza plagale</b>. Morbida e dolce, senza la sensibile che tira. È l’“A-men” cantato alla fine degli inni.',{clef:'g',cols:['F2_b C4_b F4_t A4_t=IV','C3_b C4_b E4_t G4_t=I']}]];
C[74]=[
 ['A phrase that stops <b>on the V</b> ends with a question: the <b>half cadence</b> (cadenza sospesa). It’s the comma or question mark of music, waiting for an answer.','Una frase che si ferma <b>sul V</b> finisce con una domanda: la <b>cadenza sospesa</b> o semicadenza. È la virgola o il punto di domanda della musica, che aspetta una risposta.',{clef:'g',cols:['F2_b C4_b F4_t A4_t=IV','G2_b B3_b D4_t G4_t=V']}],
 ['Very often a phrase that ends on V is followed by one that ends on I: question and answer, like a conversation.','Molto spesso a una frase che finisce sul V segue una frase che finisce sul I: domanda e risposta, come in una conversazione.']];
C[75]=[
 ['Before the final V → I, the dominant is usually prepared by a chord of the subdominant family: <b>IV</b>, or <b>ii</b> with its third in the bass (II6), which puts the 4th step in the bass, like IV.','Prima del V → I finale, la dominante di solito è preparata da un accordo della famiglia della sottodominante: <b>IV</b>, oppure <b>ii</b> con la terza al basso (II6), che mette al basso il 4° gradino, come il IV.',{clef:'g',cols:['F3_b A3_b D4_t F4_t=II6','G2_b B3_b D4_t G4_t=V','C3_b C4_b E4_t G4_t=I']}],
 ['The bass goes up by step 4 → 5, then leaps 5 → 1: it’s the classic way to close.','Il basso sale di grado 4 → 5, poi salta 5 → 1: è il modo classico di chiudere.']];
C[76]=[
 ['The bass alone tells you a lot. From the 5th to the 1st step: perfect (or imperfect) cadence. From the 4th to the 1st: plagal. Stops on the 5th: half cadence.','Il basso da solo dice molto. Dal 5° al 1° gradino: cadenza perfetta (o imperfetta). Dal 4° al 1°: plagale. Si ferma sul 5°: sospesa.']];
C[77]=[
 ['The soprano tells you how “full” the stop is: if it ends on the tonic, the cadence is perfect; on another note of the chord, imperfect.','Il soprano ti dice quanto è “pieno” il punto: se finisce sulla tonica, la cadenza è perfetta; su un’altra nota dell’accordo, imperfetta.']];
C[78]=[
 ['Just like in the Cadences game: the phrase is given, you choose the last two chords. First choose the right chords (the story: S → D → T), then the right voices.','Proprio come nel gioco delle Cadenze: la frase è data, tu scegli gli ultimi due accordi. Prima scegli gli accordi giusti (la storia: S → D → T), poi le voci giuste.']];
C[79]=[
 ['C, G and F major: the keys of the Easy level. One sharp (F♯) for G, one flat (B♭) for F. Practise the cadences in all three.','Do, Sol e Fa maggiore: le tonalità del livello Easy. Un diesis (Fa♯) per Sol, un bemolle (Si♭) per Fa. Esercitati con le cadenze in tutte e tre.',{key:1,cols:[]}]];
/* ======================= 8. INVERSIONS IN PRACTICE ======================= */
C[81]=[
 ['In root position the bass always leaps. With the <b>first inversion</b> it can walk by step instead, like a melody. I – V6 – I: the bass goes C – B – C.','In stato fondamentale il basso salta sempre. Con il <b>primo rivolto</b> può invece camminare di grado, come una melodia. I – V6 – I: il basso fa Do – Si – Do.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=I','B2_b G3_b D4_t B4_t=V6','C3_b G3_b E4_t C5_t=I']}],
 ['Use first inversions to make the bass sing, and to vary the colour: root position is solid, first inversion is lighter.','Usa i primi rivolti per far cantare il basso e per variare il colore: lo stato fondamentale è solido, il primo rivolto più leggero.']];
C[82]=[
 ['In first inversion the bass is the third of the chord. Don’t double it if it’s the leading note! Usually you double the root or the fifth.','Nel primo rivolto il basso è la terza dell’accordo. Non raddoppiarlo se è la sensibile! Di solito si raddoppia la fondamentale o la quinta.']];
C[83]=[
 ['The <b>II6</b> (ii in first inversion) is the favourite way to prepare the cadence: its bass is the 4th step, which rises by step to the 5th.','Il <b>II6</b> (ii in primo rivolto) è il modo preferito per preparare la cadenza: il suo basso è il 4° gradino, che sale di grado al 5°.',{clef:'g',cols:['F3_b A3_b D4_t F4_t=II6','G2_b B3_b D4_t G4_t=V']}]];
C[84]=[
 ['The second inversion (6/4) is delicate: it can appear only in a few places. The first: the <b>passing</b> 6/4, between two positions of the same chord, with the bass passing by step.','Il secondo rivolto (6/4) è delicato: può comparire solo in pochi posti. Il primo: la quarta e sesta <b>di passaggio</b>, tra due posizioni dello stesso accordo, con il basso che passa di grado.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=I','D3_b G3_b D4_t B4_t=V6/4','E3_b G3_b C4_t C5_t=I6']}],
 ['Like stepping stones across a stream: the 6/4 is the little stone in the middle, you just step on it and go.','Come i sassi per attraversare un ruscello: la 6/4 è il sassolino in mezzo, ci passi sopra e vai.']];
C[85]=[
 ['The <b>neighbour</b> 6/4 (di volta): the bass stays still, the upper voices move up and come back. I – IV6/4 – I, over a C held in the bass.','La quarta e sesta <b>di volta</b>: il basso resta fermo, le voci superiori salgono e tornano. I – IV6/4 – I, sopra un Do tenuto al basso.',{clef:'g',cols:['C3_b G3_b E4_t C5_t=I','C3_b A3_b F4_t C5_t=IV6/4','C3_b G3_b E4_t C5_t=I']}]];
C[86]=[
 ['The most important one: the <b>cadential</b> 6/4. Before the final V, the tonic chord appears with G in the bass (I6/4), and then becomes V over the same bass.','La più importante: la quarta e sesta <b>cadenzale</b>. Prima del V finale, l’accordo di tonica compare con il Sol al basso (I6/4), e poi diventa V sopra lo stesso basso.',{clef:'g',cols:['G2_b G3_b E4_t C5_t=6/4','G2_b G3_b D4_t B4_t=5/3','C3_b G3_b E4_t C5_t=I']}],
 ['It sounds like a long, dramatic breath before the end: you hear it in every classical concerto, just before the soloist’s cadenza.','Suona come un lungo respiro drammatico prima della fine: lo senti in ogni concerto classico, subito prima della cadenza del solista.']];
C[87]=[
 ['Mixed exercises: inversions, figures, and the cadential 6/4.','Esercizi misti: rivolti, numerica e quarta e sesta cadenzale.']];
/* ======================= 9. SEVENTH CHORDS ======================= */
C[89]=[
 ['Take a triad and stack <b>one more third</b> on top: four notes. The new note is a seventh above the root, so this is a <b>seventh chord</b>.','Prendi una triade e impila <b>un’altra terza</b> in cima: quattro note. La nota nuova sta una settima sopra la fondamentale, quindi è un <b>accordo di settima</b>.',{kbd:K('G4','G5',{'G4':'y','B4':'y','D5':'y','F5':'p'},{top:{'G4':'1','B4':'3','D5':'5','F5':'7'}}),cols:['G4 B4 D5','G4 B4 D5 F5']}],
 ['On the piano: the same “skip one key” game, with four fingers. The seventh adds a pinch of salt: the chord becomes richer and more restless.','Sul pianoforte: lo stesso gioco del “salta un tasto”, con quattro dita. La settima aggiunge un pizzico di sale: l’accordo diventa più ricco e più inquieto.']];
C[90]=[
 ['The most important seventh chord is built on the 5th step: the <b>dominant seventh</b>, <b>V7</b>. In C major: G–B–D–F.','L’accordo di settima più importante si costruisce sul 5° gradino: la <b>settima di dominante</b>, <b>V7</b>. In Do maggiore: Sol–Si–Re–Fa.',{cols:['G4 B4 D5 F5=V7']}],
 ['It has a major triad below and a minor seventh on top. It wants to go home even more than V: it contains both the leading note (B) and the F, which want to move.','Ha una triade maggiore sotto e una settima minore sopra. Vuole tornare a casa ancora più del V: contiene sia la sensibile (Si) sia il Fa, che vogliono muoversi.']];
C[91]=[
 ['How V7 goes to I: the leading note <b>goes up</b> to the tonic (B → C), the seventh <b>goes down</b> by step (F → E). Two magnets pulling in opposite directions.','Come il V7 va sul I: la sensibile <b>sale</b> alla tonica (Si → Do), la settima <b>scende</b> di grado (Fa → Mi). Due calamite che tirano in direzioni opposte.',{kbd:K('C4','C5',{'B4':'p','C5':'y','F4':'p','E4':'y'},{arcs:[['B4','C5',['up','su'],1],['F4','E4',['down','giù'],1]]}),cols:['G4 B4 D5 F5','C4 E4 G4 C5']}]];
C[92]=[
 ['A seventh chord has four notes, so it has three inversions. Their figures: root position <b>7</b>; third in the bass <b>6/5</b>; fifth in the bass <b>4/3</b>; seventh in the bass <b>2</b>.','Un accordo di settima ha quattro note, quindi ha tre rivolti. La numerica: stato fondamentale <b>7</b>; terza al basso <b>6/5</b>; quinta al basso <b>4/3</b>; settima al basso <b>2</b>.',{cols:['G4 B4 D5 F5=7','B4 D5 F5 G5=6/5','D5 F5 G5 B5=4/3','F4 G4 B4 D5=2']}],
 ['A trick: the numbers go down, 7 → 6/5 → 4/3 → 2, like a countdown.','Un trucco: i numeri scendono, 7 → 6/5 → 4/3 → 2, come un conto alla rovescia.']];
C[93]=[
 ['The golden rule of every seventh: <b>the seventh goes down</b> by step. Always. Like a leaf falling from a tree.','La regola d’oro di ogni settima: <b>la settima scende</b> di grado. Sempre. Come una foglia che cade dall’albero.']];
C[94]=[
 ['You can add a seventh to other chords too. On the 2nd step: <b>ii7</b> (D–F–A–C). Often in first inversion, <b>ii6/5</b>, with the 4th step in the bass: the perfect preparation for V.','Puoi aggiungere una settima anche ad altri accordi. Sul 2° gradino: <b>ii7</b> (Re–Fa–La–Do). Spesso in primo rivolto, <b>ii6/5</b>, con il 4° gradino al basso: la preparazione perfetta per il V.',{cols:['D4 F4 A4 C5=ii7','F4 A4 C5 D5=ii6/5']}]];
C[95]=[
 ['On the 7th step: B–D–F–A. A diminished triad plus a minor seventh: the <b>half-diminished</b> seventh, written ø. Soft and mysterious.','Sul 7° gradino: Si–Re–Fa–La. Una triade diminuita più una settima minore: la settima <b>semidiminuita</b>, scritta ø. Morbida e misteriosa.',{cols:['B4 D5 F5 A5=viiø7']}]];
C[96]=[
 ['If you stack <b>three minor thirds</b> (3+3+3), you get the <b>diminished seventh</b>: B–D–F–A♭. It divides the octave into four equal parts, so it sounds the same from every note.','Se impili <b>tre terze minori</b> (3+3+3), ottieni la <b>settima diminuita</b>: Si–Re–Fa–La♭. Divide l’ottava in quattro parti uguali, quindi suona uguale da ogni nota.',{kbd:K('A4','A5',{'B4':'y','D5':'y','F5':'y','G#5':'p'},{arcs:[['B4','D5',['3','3'],0],['D5','F5',['3','3'],0],['F5','G#5',['3','3'],0]]}),cols:['B4 D5 F5 Ab5']}],
 ['It’s the chord of suspense in old films, when the villain appears! We’ll meet it again later.','È l’accordo della suspense nei vecchi film, quando arriva il cattivo! Lo ritroveremo più avanti.']];
C[97]=[
 ['Mixed exercises on seventh chords. Remember: one more third on top, and the seventh goes down.','Esercizi misti sugli accordi di settima. Ricorda: una terza in più in cima, e la settima scende.']];
window.HM_CARDS=C;window.HM_EX=E;
})();
